"""Rebuild outputs/M03_summary.md from the 11 input CSVs (run from the repo root:
python tools/make_m03_summary.py). Also rewrites each outputs/M03_Valuation_<TICKER> report."""
import sys
from dataclasses import replace
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from m03.dcf import value  # noqa: E402
from m03.run import load, num, run, wacc_for  # noqa: E402

TICKERS = "PYPL ZTS BSX JKHY HUBB AME ETN ADI ISRG LLY MPWR".split()

L = ["# M03 summary: DCF value vs price (standard method)", "",
     "Generated by `python tools/make_m03_summary.py` from `inputs/m03/<TICKER>_dcf_inputs.csv` "
     "(teammate-corrected inputs of 23 Oct: 22 Oct closes, verified cash and diluted shares). "
     "Same method for every company: 10-year FCFF forecast (5 stated years, then growth fading "
     "to 3%), FY0 margin held flat, beta 1.0, equity premium 5%, 10-year Treasury 5.13%, terminal "
     "growth 3% with reinvestment g / 15%. Values are research estimates under these assumptions: "
     "not price targets, returns or position sizes.", "",
     "| Ticker | Value / share | Price (22 Oct) | Value / price | Ratio at measured beta | "
     "Ratio at adjusted beta | Growth shift the price implies | Terminal share of EV | Open data gaps |",
     "|---|---|---|---|---|---|---|---|---|"]
for t in TICKERS:
    p, v, shift, price = run(t)
    _, raw, rows = load(t)
    b = num(raw, "beta_measured")
    ratios = [value(replace(p, wacc=wacc_for(raw, beta)))["per_share"] / price
              for beta in (b, 0.67 * b + 0.33)]
    open_gaps = []
    if "sbc_pct" in rows and num(raw, "sbc_pct") is None:
        d = v["per_share"] - value(replace(p, sbc_pct=0.01))["per_share"]
        open_gaps.append(f"stock-based pay MISSING (-${d:,.2f}/share per 1% of revenue)")
    if "net_interest_pct" in rows and num(raw, "net_interest_pct") is None:
        open_gaps.append("EBIT = pretax (value understated)")
    L.append(f"| {t} | ${v['per_share']:,.2f} | ${price:,.2f} | {v['per_share'] / price:.2f} | "
             f"{ratios[0]:.2f} (beta {b:.2f}) | {ratios[1]:.2f} | "
             f"{'n/a' if shift is None else f'{shift:+.1%}'} | {v['terminal_share_of_ev']:.0%} | "
             f"{'; '.join(open_gaps) or 'none'} |")
L += ["", "The growth shift is added to every forecast year's revenue growth. Measured betas: "
      "60 monthly returns, Oct 2021-Sep 2026 (research update 23 Oct); adjusted = 0.67 x "
      "measured + 0.33. Pat chooses the beta; the DCF still uses 1.0.", "",
      "Known limits: cash and debt are at the base-year end (interim debt not yet collected), "
      "and the D&A row is a cash-flow calibration that still contains working-capital and tax "
      "effects. Trust the ranking more than any single value."]
Path("outputs/M03_summary.md").write_text("\n".join(L) + "\n")
print("\n".join(L[7:7 + len(TICKERS) + 1]))
